```python
import itertools

def time_to_minutes(t_str):
    """Convert time string (e.g., '9:00AM') to minutes since midnight."""
    time_part, ampm = t_str[:-2], t_str[-2:]
    hour, minute = map(int, time_part.split(':'))
    if ampm == 'AM':
        if hour == 12:
            hour = 0
    else:  # PM
        if hour != 12:
            hour += 12
    return hour * 60 + minute

def minutes_to_time(m):
    """Convert minutes since midnight to time string (e.g., '9:00AM')."""
    hour = m // 60
    minute = m % 60
    if hour == 0:
        return f"12:{minute:02d}AM"
    elif hour < 12:
        return f"{hour}:{minute:02d}AM"
    elif hour == 12:
        return f"12:{minute:02d}PM"
    else:
        return f"{hour-12}:{minute:02d}PM"

class Friend:
    def __init__(self, name, location, window_start_str, window_end_str, min_duration):
        self.name = name
        self.location = location
        self.window_start = time_to_minutes(window_start_str)
        self.window_end = time_to_minutes(window_end_str)
        self.min_duration = min_duration

def simulate_schedule(start_location, start_time_str, friends_perm, travel_times):
    """Simulate visiting friends in given order.
    Returns (success, actions) where actions is list of strings if successful."""
    current_time = time_to_minutes(start_time_str)
    current_loc = start_location
    actions = [f"You start at {start_location} at {start_time_str}."]

    for friend in friends_perm:
        # Travel to friend's location
        travel_time = travel_times[current_loc][friend.location]
        arrival = current_time + travel_time
        arrival_str = minutes_to_time(arrival)
        actions.append(f"You travel to {friend.location} in {travel_time} minutes and arrive at {arrival_str}.")

        # Check if we can meet within window
        if arrival > friend.window_end:
            return False, []  # Arrive after window closes

        # Determine start time (wait if early)
        start_meeting = max(arrival, friend.window_start)
        if arrival < friend.window_start:
            wait_until_str = minutes_to_time(friend.window_start)
            actions.append(f"You wait until {wait_until_str}.")

        # Check if we can meet for minimum duration
        end_meeting = start_meeting + friend.min_duration
        if end_meeting > friend.window_end:
            return False, []  # Cannot meet long enough

        # Record meeting
        start_str = minutes_to_time(start_meeting)
        end_str = minutes_to_time(end_meeting)
        actions.append(f"You meet {friend.name} for {friend.min_duration} minutes from {start_str} to {end_str}.")

        # Update current state
        current_loc = friend.location
        current_time = end_meeting

    return True, actions

def main():
    # Define travel times (asymmetric)
    travel_times = {
        "Nob Hill": {
            "North Beach": 8,
            "Fisherman's Wharf": 11,
            "Bayview": 19
        },
        "North Beach": {
            "Nob Hill": 7,
            "Fisherman's Wharf": 5,
            "Bayview": 22
        },
        "Fisherman's Wharf": {
            "Nob Hill": 11,
            "North Beach": 6,
            "Bayview": 26
        },
        "Bayview": {
            "Nob Hill": 20,
            "North Beach": 21,
            "Fisherman's Wharf": 25
        }
    }

    # Define friends
    friends = [
        Friend("Helen", "North Beach", "7:00AM", "4:45PM", 120),
        Friend("Kimberly", "Fisherman's Wharf", "4:30PM", "9:00PM", 45),
        Friend("Patricia", "Bayview", "6:00PM", "9:15PM", 120)
    ]

    start_location = "Nob Hill"
    start_time_str = "9:00AM"

    best_count = 0
    best_actions = None

    # Consider all non-empty subsets of friends
    for subset_size in range(1, len(friends)+1):
        for subset in itertools.combinations(friends, subset_size):
            # For each permutation of the subset
            for perm in itertools.permutations(subset):
                success, actions = simulate_schedule(start_location, start_time_str, perm, travel_times)
                if success:
                    count = len(perm)
                    if count > best_count:
                        best_count = count
                        best_actions = actions
                    # If we already found a schedule with all friends, we can stop early
                    if best_count == len(friends):
                        break
            if best_count == len(friends):
                break
        if best_count == len(friends):
            break

    # Output the best schedule found
    if best_actions:
        print(best_actions)
    else:
        print("No feasible schedule found.")

if __name__ == "__main__":
    main()
```

