    Returns (success, actions) where actions is list of strings if successful."""
    current_time = time_to_minutes(start_time_str)
    current_loc = start_location
    actions = [f"You start at {start_location} at {start_time_str}."]

    for friend in friends_perm:
        # Travel to friend's location
        travel_time = travel_times[current_loc][friend.location]
        arrival = current_time + travel_time
        arrival_str = minutes_to_time(arrival)
        actions.append(f"You travel to {friend.location} in {travel_time} minutes and arrive at {arrival_str}.")

        # Check if we can meet within window
        if arrival > friend.window_end:
            return False, []  # Arrive after window closes

        # Determine start time (wait if early)
        start_meeting = max(arrival, friend.window_start)
        if arrival < friend.window_start:
            wait_until_str = minutes_to_time(friend.window_start)
            actions.append(f"You wait until {wait_until_str}.")

        # Check if we can meet for minimum duration
        end_meeting = start_meeting + friend.min_duration
        if end_meeting > friend.window_end:
            return False, []  # Cannot meet long enough

        # Record meeting
        start_str = minutes_to_time(start_meeting)
        end_str = minutes_to_time(end_meeting)
        actions.append(f"You meet {friend.name} for {friend.min_duration} minutes from {start_str} to {end_str}.")

        # Update current state
        current_loc = friend.location
        current_time = end_meeting

    return True, actions

def main():
    # Define travel times (asymmetric)
    travel_times = {
        "Nob Hill": {
            "North Beach": 8,
            "Fisherman's Wharf": 11,
            "Bayview": 19
        },
        "North Beach": {
            "Nob Hill": 7,
            "Fisherman's Wharf": 5,
