        },
        "Fisherman's Wharf": {
            "Nob Hill": 11,
            "North Beach": 6,
            "Bayview": 26
        },
        "Bayview": {
            "Nob Hill": 20,
            "North Beach": 21,
            "Fisherman's Wharf": 25
        }
