        Friend("Patricia", "Bayview", "6:00PM", "9:15PM", 120)
    ]

    start_location = "Nob Hill"
    start_time_str = "9:00AM"

    best_count = 0
    best_actions = None

    # Consider all non-empty subsets of friends
    for subset_size in range(1, len(friends)+1):
        for subset in itertools.combinations(friends, subset_size):
            # For each permutation of the subset
            for perm in itertools.permutations(subset):
                success, actions = simulate_schedule(start_location, start_time_str, perm, travel_times)
                if success:
                    count = len(perm)
                    if count > best_count:
                        best_count = count
                        best_actions = actions
                    # If we already found a schedule with all friends, we can stop early
                    if best_count == len(friends):
                        break
            if best_count == len(friends):
                break
        if best_count == len(friends):
            break

    # Output the best schedule found
    if best_actions:
        print(best_actions)
    else:
        print("No feasible schedule found.")

if __name__ == "__main__":
    main()
