import itertools
from typing import List, Dict, Tuple, Optional

def time_to_minutes(t: str) -> int:
    """Convert time string (e.g., '9:00AM' or '2:15PM') to minutes since midnight."""
    t = t.strip().upper()
    if 'AM' in t or 'PM' in t:
        time_part, meridiem = t[:-2], t[-2:]
        hours, minutes = map(int, time_part.split(':'))
        if meridiem == 'PM' and hours != 12:
            hours += 12
        if meridiem == 'AM' and hours == 12:
            hours = 0
        return hours * 60 + minutes
    else:
        # Assume format is already 24-hour? Not needed here.
        raise ValueError(f"Time format not recognized: {t}")

def minutes_to_time_str(m: int) -> str:
    """Convert minutes since midnight to time string like '9:00AM'."""
    hours = m // 60
    minutes = m % 60
    if hours == 0:
        return f"12:{minutes:02d}AM"
    elif hours < 12:
        return f"{hours}:{minutes:02d}AM"
    elif hours == 12:
        return f"12:{minutes:02d}PM"
    else:
        return f"{hours-12}:{minutes:02d}PM"

class Friend:
    def __init__(self, name: str, location: str, avail_start: str, avail_end: str, min_duration: int):
        self.name = name
        self.location = location
        self.avail_start_min = time_to_minutes(avail_start)
        self.avail_end_min = time_to_minutes(avail_end)
        self.min_duration = min_duration

def schedule_meetings(start_loc: str, start_time_str: str, friends: List[Friend], travel_times: Dict[str, Dict[str, int]]) -> List[str]:
    """Return optimal schedule as a list of action strings."""
    start_time = time_to_minutes(start_time_str)
    best_schedule = []
    best_count = 0
    # Consider all subsets of friends (non-empty)
    for k in range(1, len(friends)+1):
        for subset in itertools.combinations(friends, k):
            for perm in itertools.permutations(subset):
                current_time = start_time
                current_loc = start_loc
                actions = []
                feasible = True
                for friend in perm:
                    # Get travel time; assume 0 if same location
                    travel = travel_times.get(current_loc, {}).get(friend.location, 0)
                    arrival = current_time + travel
                    # Travel action if travel > 0
                    if travel > 0:
                        actions.append(f"You travel to {friend.location} in {travel} minutes and arrive at {minutes_to_time_str(arrival)}.")
                    # Check if we can meet
                    if arrival > friend.avail_end_min:
                        feasible = False
                        break
                    start_meeting = max(arrival, friend.avail_start_min)
                    if start_meeting + friend.min_duration > friend.avail_end_min:
                        feasible = False
                        break
                    # Wait action if we arrive early
                    if arrival < friend.avail_start_min:
                        actions.append(f"You wait until {minutes_to_time_str(friend.avail_start_min)}.")
                    # Meeting action
                    end_meeting = start_meeting + friend.min_duration
                    actions.append(f"You meet {friend.name} for {friend.min_duration} minutes from {minutes_to_time_str(start_meeting)} to {minutes_to_time_str(end_meeting)}.")
                    # Update state
                    current_time = end_meeting
                    current_loc = friend.location
                if feasible and len(perm) > best_count:
                    best_count = len(perm)
                    best_schedule = actions.copy()
    # Prepend start action
    if best_schedule:
        best_schedule.insert(0, f"You start at {start_loc} at {start_time_str}.")
    return best_schedule

def main():
    # Define travel times: a dictionary from location to dictionary of destinations and minutes.
    travel_times = {
        "Fisherman's Wharf": {"Nob Hill": 11},
        "Nob Hill": {"Fisherman's Wharf": 11}
    }
    # Start location and time
    start_loc = "Fisherman's Wharf"
    start_time = "9:00AM"
    # Define friends (only Kenneth in this case)
    friends = [
        Friend("Kenneth", "Nob Hill", "2:15PM", "7:45PM", 90)
    ]
    # Get optimal schedule
    schedule = schedule_meetings(start_loc, start_time, friends, travel_times)
    # Output
    if schedule:
        print(schedule)
    else:
        print("No feasible meetings found.")

if __name__ == "__main__":
    main()
